/// [packageType] The type of supported package. Packages in GitHub's Gradle
///   registry have the type `maven`. Docker images pushed to GitHub's Container
///   registry (`ghcr.io`) have the type `container`. You can use the type
///   `docker` to find images that were pushed to GitHub's Docker registry
///   (`docker.pkg.github.com`), even if these have now been migrated to the
///   Container registry.
/// [packageName] The name of the package.
/// [username] The handle for the GitHub user account.
/// [packageVersionId] Unique identifier of the package version.
Future<void> packagesRestorePackageVersionForUser(ClientConfig config,
    {required SchemaSchema5f6fac39 packageType,
    required String packageName,
    required String username,
    required int packageVersionId,
    RequestOptions? requestOptions}) async {
  return (await sdkRequest<void>('POST',
          '/users/${Uri.encodeComponent(username.toString())}/packages/${Uri.encodeComponent(packageType.toString())}/${Uri.encodeComponent(packageName.toString())}/versions/${Uri.encodeComponent(packageVersionId.toString())}/restore',
          config: config,
          decoder: SdkResponseDecoder.empty,
          operationId: 'packagesRestorePackageVersionForUser',
          options: requestOptions,
          errors: {
        '401': (value) => BasicError.fromJson(value as Map<String, dynamic>),
        '403': (value) => BasicError.fromJson(value as Map<String, dynamic>),
        '404': (value) => BasicError.fromJson(value as Map<String, dynamic>)
      }))
      .data;
}
